{% assign scores = staff | map: "score" %}
{% assign leads = staff | where: "lead", true %}
{% assign average = scores | sum | divided_by: staff.size %}
{% assign top = staff | sort: "score" | reverse | first %}



{{ heading | default: "Badge sheet" | upcase | fit: 380, 17 | escape }}
{{ staff.size }} entries · avg {{ average | round: 1 }} · {{ leads.size }} lead · top {{ top.name | fit: 90, 10 | escape }}


RENDER · one fragment per entry
{% for row in staff %}
  {% assign col = forloop.index0 | modulo: 2 %}
  {% comment %}liquidjs divides as floats, so round the row down.{% endcomment %}
  {% assign line = forloop.index0 | divided_by: 2 | floor %}
  {% comment %}
    A filter cannot go in a tag argument: `x: col | times: 306, y: 70` reads
    `y: 70` as a second argument to `times`. Assign first, pass the name.
  {% endcomment %}
  {% assign bx = col | times: 306 | plus: 16 %}
  {% assign by = line | times: 56 | plus: 70 %}
  {% render "badge.svg", x: bx, y: by, name: row.name, code: row.dept.code,
      score: row.score, lead: row.lead, trend: row.trend %}
{% endfor %}


